    (1, 4633, 13, 'CLORURO DE SODIO/SOLUCION ISITINICO 100ML AL 9% - BONIN'),
    (1, 4094, 12, 'VOLUVEN SOLUCION INYECTABLE FCO. 500 ML CONSIG XG *'),
    (1, 4115, 13, '3 GEL-SUSPENSION SOBRES'),
