    (1, 4125, 13, 'ACIDO AMINOCAPROICO 5 G/20ML VIAL'),
    (1, 4126, 13, 'ACIDO TRICLOROACETICO 10 ML.'),
    (1, 4127, 13, 'ACI-TIP 200/200mg Hidrox.Magnesio/Aluminio Comprimidos'),
    (1, 4128, 13, 'ACI-TIP 4/4.4mg Hidróx.Magnesio/Aluminio Suspensión Fco200ml'),
