alter table public.productos add column if not exists proveedor_codigo_anterior integer;
alter table public.productos add column if not exists estado_original text;
alter table public.productos add column if not exists tipo_articulo_anterior integer;
alter table public.productos add column if not exists revi_exis_inv boolean;
alter table public.productos add column if not exists producto_ant integer;
alter table public.productos add column if not exists codigo_producto_anterior text;
alter table public.productos add column if not exists usuario_ingresa_anterior text;
alter table public.productos add column if not exists fecha_ingresa_anterior date;
