    (2, 2222, 'CLAVO DE KIRSCHNER 0.45 138-15230', 0, 9, 'INACTIVO', 'I', 1, 1, 'S', null, null, null, null, 1, 1, 1, null, null, null, null, null, null, null, null, null, false, null, false, 2, 0, false, null, null, null, null, null),
