        clasificacion_lab = r.clas_lab, revisado = r.revisado, generico_anterior = r.generico, codigo_barras_anterior = r.barras_ant,
        minimo_anterior = r.minimo, maximo_anterior = r.maximo
      where id = v_id;
      v_a := v_a + 1;
    end if;
  end loop;
  raise notice '%', format('Parte 9 de 13: %s productos nuevos, %s actualizados. Sin tipo de producto: %s; con tipo de otra clasificación (se deja sin tipo): %s; con proveedor aún no migrado: %s.',
    v_n, v_a, v_sintipo, v_otra, v_sinprov);
end;
